/* AMC action toolbar remains reachable without horizontally scrolling the table. */
function amcContractByKey(value){let [key,id]=String(value||'').split('|');return amcContractEntries().find(e=>e.contractKey===key&&e.contractId===id)}
function renewAmcContract(key,id,data){let record=find(key,id);if(!record)throw Error('AMC record not found.');validateCustomerAmc(data);let before=structuredClone(db);db.amcRenewals=db.amcRenewals||[];db.amcRenewals.push({id:'AMC-RENEW-'+Date.now(),key,record:id,renewedAt:new Date().toISOString(),previous:{amcType:record.amcType||'',amcPlanId:record.amcPlanId||'',amcStart:record.amcStart||'',amcExpiry:record.amcExpiry||'',amcRef:record.amcRef||''},next:{...data}});Object.assign(record,data);if(key==='bikes')record.amcScope='vehicle';audit('AMC Renewal',id+' renewed until '+data.amcExpiry);if(save('AMC renewed; linked screens updated')===false){db=before;return false}return true}
function openAmcRenewal(entry){if(!entry)return toast('Add an AMC contract first.');let plan=findAmcPlan(entry.amcPlanId,entry.amcType),start=today();if(validAmcDate(entry.amcExpiry)&&entry.amcExpiry>=start){let next=new Date(entry.amcExpiry+'T00:00:00Z');next.setUTCDate(next.getUTCDate()+1);start=next.toISOString().slice(0,10)}let values={amcPlanId:plan?.id||'',amcStart:start,amcExpiry:suggestedAmcExpiry(start,plan?.months||12),amcRef:entry.amcRef||''};openModal('Renew AMC — '+entry.name,`<form id="renewAmcContract"><div class="formbody"><p>${esc(entry.amcType)} · Current expiry: ${esc(entry.amcExpiry||'Not set')}. Review the new validity dates before saving.</p><div class="formgrid">${field({key:'amcPlanId',label:'AMC Plan',type:'select',options:()=>db.amcPlans.map(p=>({value:p.id,label:p.name})),required:true},values)}${field({key:'amcStart',label:'Renewal Valid From',type:'date',required:true},values)}${field({key:'amcExpiry',label:'Renewal Valid Until',type:'date',required:true},values)}${field({key:'amcRef',label:'Agreement Reference'},values)}</div></div><div class="formactions">${btn('Cancel','cancel','secondary')}<button class="btn" type="submit">Confirm Renewal</button></div></form>`);let form=$('#renewAmcContract');form.onsubmit=e=>{e.preventDefault();try{let data=Object.fromEntries(new FormData(form)),p=findAmcPlan(data.amcPlanId);if(!p)throw Error('Choose an AMC plan.');data.amcType=p.name;if(renewAmcContract(entry.contractKey,entry.contractId,data)){closeModal();render()}}catch(err){toast(err.message)}}}
function performAmcAction(action,value){let entry=amcContractByKey(value);if(!entry)return toast('Select an AMC contract, or use Add AMC to create one.');if(action==='edit')return editRecord(entry.contractKey,entry.contractId);if(action==='renew')return openAmcRenewal(entry);if(action==='whatsapp'){if(amcExpiryDays(entry)===null)return toast('Set a valid AMC expiry date first.');return messagePreview(entry.mobile,amcExpiryMessage(entry)+(entry.vehicleNumbers?'\nVehicle(s): '+entry.vehicleNumbers:''))}if(action==='history'){let logs=(db.amcReminderLogs||[]).filter(l=>entry.contractKey==='bikes'?l.vehicle===entry.contractId:l.customer===entry.contractId&&!l.vehicle);return openModal('AMC Reminder History',`<div class="formbody"><h3>${esc(entry.name)} · ${esc(entry.amcType)}</h3>${table(['Recorded At','Expiry Date','Status','Notes'],logs.map(l=>[esc(uiDateTime(l.at)),esc(l.expiryDate),esc(l.status),esc(l.note||'—')]))}${!logs.length?'<p>No reminder history recorded yet.</p>':''}</div><div class="formactions">${btn('Close','cancel','secondary')}</div>`)}if(action==='sent'){openModal('Record AMC Reminder Sent',`<form id="amcActionSentForm"><div class="formbody"><p>Confirm you sent the reminder to ${esc(entry.name)}. This records your confirmation; it does not send a message.</p><input name="note" maxlength="500" placeholder="Contact method / notes"></div><div class="formactions">${btn('Cancel','cancel','secondary')}<button type="submit" class="btn">Confirm Sent</button></div></form>`);$('#amcActionSentForm').onsubmit=e=>{e.preventDefault();try{if(logAmcContractReminder(entry.contractKey,entry.contractId,new FormData(e.target).get('note'))){closeModal();render()}}catch(err){toast(err.message)}}}}
function amcActionPanel(){let entries=amcContractEntries();return `<section class="amcActionPanel"><h3>AMC Actions</h3><label class="field"><span>Select Customer / Vehicle AMC</span><select id="amcActionContract">${entries.length?opts(entries.map(e=>({value:e.contractKey+'|'+e.contractId,label:e.name+' · '+(e.vehicleNumbers||'Customer AMC')+' · '+e.amcType}))):'<option value="">No AMC contracts — add one first</option>'}</select></label><div class="amcActionButtons"><button class="btn" type="button" id="amcActionAdd">Add AMC</button>${[['whatsapp','WhatsApp Reminder'],['edit','Edit AMC'],['renew','Renew AMC'],['sent','Record Sent'],['history','History']].map(([action,label])=>`<button class="btn ${action==='whatsapp'?'success':'secondary'}" type="button" data-amc-toolbar-action="${action}" ${entries.length?'':'disabled'}>${action==='whatsapp'?whatsappIcon():''}${label}</button>`).join('')}</div></section>`}
const amcPageBeforeExplicitActions=amcRemindersPage;
amcRemindersPage=function(){return amcActionPanel()+amcPageBeforeExplicitActions()};
const renderBeforeExplicitAmcActions=render;
render=function(){renderBeforeExplicitAmcActions();if(page!=='amc-reminders'&&!(page==='service-reminders'&&reminderView==='amc'))return;if($('#amcActionAdd'))$('#amcActionAdd').onclick=openReminderAmcRecord;for(let button of $$('[data-amc-toolbar-action]'))button.onclick=()=>performAmcAction(button.dataset.amcToolbarAction,$('#amcActionContract').value);for(let button of $$('[data-contract-message]')){let value=button.dataset.contractMessage,container=button.closest('.rowactions');if(!container)continue;button.innerHTML=whatsappIcon()+'<span>WhatsApp Reminder</span>';button.onclick=()=>performAmcAction('whatsapp',value);let edit=container.querySelector('[data-edit]');if(edit)edit.innerHTML=icon('edit')+'<span>Edit AMC</span>';let sent=container.querySelector('[data-contract-sent]');if(sent){sent.innerHTML=icon('check')+'<span>Record Sent</span>';sent.onclick=()=>performAmcAction('sent',value)}for(let [action,label]of [['renew','Renew AMC'],['history','History']]){let extra=document.createElement('button');extra.type='button';extra.className='btn small secondary';extra.textContent=label;extra.onclick=()=>performAmcAction(action,value);container.appendChild(extra)}let cell=container.closest('td');if(cell)cell.classList.add('amcVisibleActionCell')}};
render();
